import pathlib,json,base64,hashlib,subprocess,shutil,fcntl,importlib.util,time,os
ROOT=pathlib.Path('/opt/qq-farm-autoupdate');PACKAGE=ROOT/'network-recovery-v1'
FILES = {'network_recovery.py': '', 'tests/test_network_recovery.py': '', 'core-tests/network-recovery-fence.test.js': '', 'core-tests/network-recovery-routes.test.js': '', 'legacy-tests/test_guard_login.py': ''}
baseline=json.loads((ROOT/'network-recovery-baseline-20261030.json').read_text())
def sha(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def inspect():return json.loads(subprocess.check_output(['docker','inspect','qq-farm-bot'],text=True))[0]
def check_preservation():
 assert sha('/root/qq-farm-guard.py')==baseline['guard_hash'],'Guard changed'
 assert sha('/opt/qq-farm-bot/.env')==baseline['env_hash'],'Environment changed'
 assert all(sha(p)==h for p,h in baseline['config_hashes'].items()),'Account settings changed; inspect before proceeding'
with open('/run/qq-farm-deploy.lock','a') as lock:
 fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 assert not (ROOT/'transaction.json').exists() and not pathlib.Path('/run/qq-farm-autoupdate-deploy.pause').exists()
 i=inspect();labels=i['Config'].get('Labels',{})
 assert labels.get('qq-farm.milk-tea-automation')=='milk-tea-auto-v5','v5 not deployed'
 assert labels.get('qq-farm.network-recovery')=='network-recovery-v1'
 assert i['State'].get('Health',{}).get('Status')=='healthy'
 check_preservation()
 if pathlib.Path('/etc/systemd/system/qq-farm-network-recovery.timer').exists():
  subprocess.run(['systemctl','stop','qq-farm-network-recovery.timer'],check=True)
 backup=pathlib.Path('/opt/backups/qq-farm-bot')/time.strftime('network-recovery-%Y%m%d-%H%M%S');backup.mkdir(mode=0o700)
 for p in [ROOT/'network-recovery-config.json',ROOT/'network-recovery-state.json',pathlib.Path('/etc/systemd/system/qq-farm-network-recovery.service'),pathlib.Path('/etc/systemd/system/qq-farm-network-recovery.timer')]:
  if p.exists():shutil.copy2(p,backup/p.name)
 if PACKAGE.exists():shutil.copytree(PACKAGE,backup/'package')
 PACKAGE.mkdir(mode=0o700,exist_ok=True)
 for name,data in FILES.items():
  target=(PACKAGE/name).resolve();assert PACKAGE.resolve() in target.parents
  target.parent.mkdir(mode=0o700,parents=True,exist_ok=True);raw=base64.b64decode(data)
  target.write_bytes(raw);target.chmod(0o644 if name.startswith('core-tests/') else 0o600)
  if name.startswith('core-tests/'):target.parent.chmod(0o755)
 subprocess.run(['python3','-m','unittest','discover','-s',str(PACKAGE/'tests'),'-v'],check=True)
 subprocess.run(['python3',str(PACKAGE/'legacy-tests/test_guard_login.py'),'/root/qq-farm-guard.py'],check=True)
 subprocess.run(['docker','run','--rm','--network=none','--tmpfs','/app/core/data:rw,size=16m','--mount','type=bind,source='+str(PACKAGE/'core-tests')+',target=/app/core/tests,readonly','--entrypoint','node',i['Image'],'--test','/app/core/tests/network-recovery-fence.test.js','/app/core/tests/network-recovery-routes.test.js'],check=True)
 spec=importlib.util.spec_from_file_location('verified_network_recovery',PACKAGE/'network_recovery.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
 panel=m.Panel();account=panel.account('2');observation=panel.observe('2')
 assert account and account.get('running') and observation['online'],'Account2 must be online before enabling watcher'
 assert panel.profile_hash()==baseline['profile_hash'],'QQ identity changed; retain manual control'
 config={'enabled':True,'account_id':'2','profile_hash':baseline['profile_hash'],'capability':'network-recovery-v1'}
 m.atomic_json(ROOT/'network-recovery-config.json',config)
 state_path=ROOT/'network-recovery-state.json'
 prior_state=json.loads(state_path.read_text()) if state_path.exists() else {}
 seeded_at=time.time()
 m.atomic_json(state_path,{'armed':False,'attempts':prior_state.get('attempts',[])})
 service='''[Unit]
Description=Bounded QQ Farm network recovery
After=docker.service network-online.target
Requires=docker.service
[Service]
Type=oneshot
ExecStart=/usr/bin/python3 /opt/qq-farm-autoupdate/network-recovery-v1/network_recovery.py
TimeoutStartSec=180
MemoryMax=160M
Nice=10
'''
 timer='''[Unit]
Description=Check QQ Farm network recovery every minute
[Timer]
OnBootSec=60
OnUnitInactiveSec=60
AccuracySec=5
Unit=qq-farm-network-recovery.service
[Install]
WantedBy=timers.target
'''
 for name,content in [('qq-farm-network-recovery.service',service),('qq-farm-network-recovery.timer',timer)]:
  target=pathlib.Path('/etc/systemd/system')/name;target.write_text(content);target.chmod(0o644)
 check_preservation();assert inspect()['State']['StartedAt']==i['State']['StartedAt']
 print('INSTALL_BACKUP',str(backup),flush=True)
subprocess.run(['systemctl','daemon-reload'],check=True)
subprocess.run(['systemctl','start','qq-farm-network-recovery.service'],check=True,timeout=45)
state=json.loads((ROOT/'network-recovery-state.json').read_text());assert state.get('armed') is True,'Watcher did not observe online account2'
assert state.get('last_online',0)>=seeded_at,'No fresh watcher observation'
current=panel.observe('2');assert current['online'] and current['fence']==state.get('fence'),'Account state changed; retain manual control'
subprocess.run(['systemctl','enable','--now','qq-farm-network-recovery.timer'],check=True)
check_preservation()
print('NETWORK_RECOVERY_INSTALLED armed=True account=2 max=3/hour cooldown=600s',flush=True)
print('ORIGINAL_GUARD_UNCHANGED',sha('/root/qq-farm-guard.py'),flush=True)
print(subprocess.check_output(['journalctl','-u','qq-farm-network-recovery.service','-n','4','--no-pager','-o','cat'],text=True),flush=True)
